import{_ as d,o,c as r,a2 as a}from"./chunks/framework.QCr1ZR1X.js";const q=JSON.parse('{"title":"教师用书 第3章 工业互联网网络互通","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch3/教师用书-第3章-工业互联网网络互通.md","filePath":"teacher/ch3/教师用书-第3章-工业互联网网络互通.md","lastUpdated":1786967935000}'),e={name:"teacher/ch3/教师用书-第3章-工业互联网网络互通.md"};function l(i,t,h,u,n,s){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="教师用书-第3章-工业互联网网络互通" tabindex="-1">教师用书 第3章 工业互联网网络互通 <a class="header-anchor" href="#教师用书-第3章-工业互联网网络互通" aria-label="Permalink to &quot;教师用书 第3章 工业互联网网络互通&quot;">​</a></h1><hr><h2 id="一、本章教学目标" tabindex="-1">一、本章教学目标 <a class="header-anchor" href="#一、本章教学目标" aria-label="Permalink to &quot;一、本章教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>理解 ISA-95 五层模型（L0~L4）的层级结构和各层关心的核心问题</li><li>掌握六种主流工业通信协议（ProfiNet、Profibus、EtherCAT、CC-Link IE、Modbus、EtherNet/IP）的特点和适用场景</li><li>理解 ISA-95 与 IIRA 两套模型的区别与联系</li><li>了解 Modbus 协议的四类寄存器（线圈、离散输入、保持寄存器、输入寄存器）和常用功能码</li><li>理解工业协议与消费互联网协议在设计理念上的根本差异</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能在 Ubuntu 虚拟机上独立安装 Node-RED 并配置开机自启</li><li>能通过浏览器访问 Node-RED Web 界面并安装社区节点</li><li>能用 Node-RED 搭建 ModbusTCP 从站（模拟传感器）和主站（模拟网关）</li><li>能使用 QModMaster 调试工具手动读写 Modbus 寄存器</li><li>能诊断&quot;通信参数不匹配&quot;类常见故障（端口、IP、从站 ID）</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ol><li>通过乌克兰电网案例理解工业协议的严谨性，培养工程安全意识</li><li>通过协议&quot;一句话口诀&quot;训练精准表达能力</li><li>通过设备&quot;语言不通&quot;的场景理解跨厂商集成的现实挑战</li></ol><hr><h2 id="二、课时分配与教学安排" tabindex="-1">二、课时分配与教学安排 <a class="header-anchor" href="#二、课时分配与教学安排" aria-label="Permalink to &quot;二、课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>内容</th><th>类型</th><th>课时</th></tr></thead><tbody><tr><td>第1次课</td><td>3.1 设备怎么对话 + ISA-95 五层地图</td><td>理论</td><td>2</td></tr><tr><td>第2次课</td><td>3.2 动手实践：安装 Node-RED</td><td>实践</td><td>2</td></tr><tr><td>第3次课</td><td>3.3 六大协议华山论剑</td><td>理论</td><td>2</td></tr><tr><td>第4次课</td><td>3.4 动手实践：ModbusTCP 通信实战</td><td>实践</td><td>2</td></tr></tbody></table><p><strong>合计：8课时（理论4 + 实践4）</strong></p><hr><h2 id="三、各节教学实施建议" tabindex="-1">三、各节教学实施建议 <a class="header-anchor" href="#三、各节教学实施建议" aria-label="Permalink to &quot;三、各节教学实施建议&quot;">​</a></h2><h3 id="第1次课-3-1-设备怎么对话-isa-95" tabindex="-1">第1次课：3.1 设备怎么对话 + ISA-95 <a class="header-anchor" href="#第1次课-3-1-设备怎么对话-isa-95" aria-label="Permalink to &quot;第1次课：3.1 设备怎么对话 + ISA-95&quot;">​</a></h3><h4 id="教学导入-10分钟" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><p>从学生熟悉的场景切入：手机和电脑都能联网是因为用了同样的协议（WiFi + TCP/IP）。然后提出问题：为什么工厂里的 FANUC 机器人、SIEMENS PLC、ABB 焊接机之间不能直接&quot;打电话&quot;？</p><p>展示图 3-1（焊装车间多协议设备示意图）的实际照片或网络拓扑图，让学生直观感受&quot;语言不通&quot;的现场。</p><h4 id="知识讲解-60分钟" tabindex="-1">知识讲解（60分钟） <a class="header-anchor" href="#知识讲解-60分钟" aria-label="Permalink to &quot;知识讲解（60分钟）&quot;">​</a></h4><p><strong>第一部分：焊装车间的四种语言（20分钟）</strong></p><p>按照教材 3.1 节的顺序讲，重点：</p><ol><li>七个设备、四种协议的表格，让学生在笔记本上记录</li><li>三种解决思路（统一协议/协议网关/通用中间层），分别举例</li><li>强调&quot;统一协议在现实中永远无法完全实现&quot;——引出学多种协议的必要性</li></ol><p><strong>第二部分：ISA-95 五层地图（40分钟）</strong></p><p>这是本章最核心的理论知识点，重点讲清楚：</p><ol><li><p>每一层&quot;关心什么问题&quot;——用具体例子说明</p><ul><li>L0：&quot;现在温度75.3℃&quot;（传感器回答&quot;是多少&quot;）</li><li>L1：&quot;如果&gt;80℃，关闭加热器&quot;（PLC回答&quot;该做什么&quot;）</li><li>L2：&quot;3号线所有设备状态——中控大屏看全局&quot;（SCADA回答&quot;整体什么样&quot;）</li><li>L3：&quot;这批订单做到哪了？&quot;（MES回答&quot;生产进行到哪了&quot;）</li><li>L4：&quot;这个月赚了还是亏了？&quot;（ERP回答&quot;经营状况如何&quot;）</li></ul></li><li><p>用类比帮助记忆：</p><ul><li>L0 = 人的感官（眼睛看、耳朵听）</li><li>L1 = 人的大脑（思考、判断）</li><li>L2 = 主管的平板电脑（看整个车间）</li><li>L3 = 车间主任的电脑（管生产计划）</li><li>L4 = 老板的办公室（管经营）</li></ul></li><li><p>ISA-95 与 IIRA 的对应关系（15分钟）</p><ul><li>ISA-95 是&quot;纵向&quot;——从传感器到 ERP（垂直方向）</li><li>IIRA 是&quot;横向&quot;——从边缘到云到业务（水平方向）</li><li>两者可以叠加使用，描述同一个工厂</li></ul></li></ol><p><strong>板书建议</strong>：在黑板上画 ISA-95 五层金字塔，每层标注层级名称、典型设备、代表问题。</p><h4 id="回顾讨论-10分钟" tabindex="-1">回顾讨论（10分钟） <a class="header-anchor" href="#回顾讨论-10分钟" aria-label="Permalink to &quot;回顾讨论（10分钟）&quot;">​</a></h4><p>让学生回答：</p><ol><li>&quot;PLC 属于哪一层？SCADA 属于哪一层？&quot;（快速点名，检验理解）</li><li>&quot;ISA-95 和 IIRA 有什么区别？&quot;（开放讨论）</li></ol><h4 id="常见问题与解答" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>解答</th></tr></thead><tbody><tr><td>&quot;PLC 到底属于 L1 还是 L2？&quot;</td><td>大多数 PLC 属于 L1（做控制逻辑）；如果 PLC 同时在做数据采集和上报，可能同时承担 L2 职责。现实中常有重叠。</td></tr><tr><td>&quot;能不能直接把所有设备换成同一套协议？&quot;</td><td>理论上可以，现实中成本极高。新设备选型时优先考虑统一，老设备用网关过渡。</td></tr><tr><td>&quot;ISA-95 和 IIRA 哪个更好用？&quot;</td><td>各有侧重。ISA-95 描述工厂内部纵向关系更清晰；IIRA 描述工业互联网整体架构更全面。两者结合使用。</td></tr></tbody></table><hr><h3 id="第2次课-3-2-动手实践-安装-node-red" tabindex="-1">第2次课：3.2 动手实践：安装 Node-RED <a class="header-anchor" href="#第2次课-3-2-动手实践-安装-node-red" aria-label="Permalink to &quot;第2次课：3.2 动手实践：安装 Node-RED&quot;">​</a></h3><h4 id="教学准备" tabindex="-1">教学准备 <a class="header-anchor" href="#教学准备" aria-label="Permalink to &quot;教学准备&quot;">​</a></h4><ul><li>确保每个学生已完成 VMware Ubuntu 虚拟机安装和网络配置（参考第1章和第2章内容）</li><li>检查 SSH 连接是否正常（教师演示：Windows 终端 SSH 登录）</li><li>预先下载好 node-red-contrib-modbus 节点的离线包（如网络较慢）</li></ul><h4 id="教学导入-5分钟" tabindex="-1">教学导入（5分钟） <a class="header-anchor" href="#教学导入-5分钟" aria-label="Permalink to &quot;教学导入（5分钟）&quot;">​</a></h4><p>Node-RED 是贯穿后续5章的核心工具，本节安装质量直接影响后续实践。本节目标：每个学生都能在浏览器里看到 Node-RED 界面。</p><h4 id="分步演示与学生操作-75分钟" tabindex="-1">分步演示与学生操作（75分钟） <a class="header-anchor" href="#分步演示与学生操作-75分钟" aria-label="Permalink to &quot;分步演示与学生操作（75分钟）&quot;">​</a></h4><p><strong>任务一：安装 Node-RED（25分钟）</strong></p><ol><li><p><strong>教师演示</strong>（10分钟）：</p><ul><li>SSH 登录 Ubuntu</li><li>粘贴安装命令</li><li>解释 <code>curl -sL</code> 的含义（静默跟随重定向）</li><li>强调：安装过程需要3-5分钟，中间不要断开网络</li></ul></li><li><p><strong>学生操作</strong>（15分钟）：跟做，教师巡视</p></li></ol><p><strong>常见问题</strong>：</p><ul><li>Node.js 版本不兼容 → 脚本会自动安装正确版本，耐心等待</li><li>网络中断 → 重新运行安装命令（幂等操作）</li></ul><p><strong>任务二：启动与开机自启（10分钟）</strong></p><p>讲解 <code>node-red-start</code> 和 <code>systemctl enable nodered</code> 的区别：前者是手动启动，后者是开机自动启动。</p><p><strong>任务三：Web 界面访问（15分钟）</strong></p><ol><li>教师演示：在 Windows 浏览器中输入 Ubuntu IP:1880</li><li>学生操作：记录自己的 Ubuntu IP，访问 Web 界面</li><li>逐一检查：确保每个学生都能看到 Node-RED 编辑界面</li></ol><p><strong>教学重点</strong>：Node-RED 的三个区域（左侧节点面板/中间 Flow 编辑区/右侧信息面板），让学生在纸上画出来并标注名称。</p><p><strong>任务四：安装 Modbus 节点（15分钟）</strong></p><ol><li>教师演示：通过 Manage palette 安装 node-red-contrib-modbus</li><li>强调：搜索时输入完整名称，不要只输入&quot;modbus&quot;</li><li>学生操作，教师巡视</li></ol><p><strong>任务五：ISA-95 关联节点（10分钟）</strong></p><p>这是本节的微环节思政点：</p><ol><li>用注释节点（Comment）画出 ISA-95 五层</li><li>用线连接，模拟数据流动方向</li><li>讲解：工具安装不是纯技术操作，要和理论结合</li></ol><h4 id="回顾讨论-5分钟" tabindex="-1">回顾讨论（5分钟） <a class="header-anchor" href="#回顾讨论-5分钟" aria-label="Permalink to &quot;回顾讨论（5分钟）&quot;">​</a></h4><p>让学生展示自己画的 ISA-95 节点图，互相评价。</p><h4 id="常见问题与解答-1" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-1" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>解答</th></tr></thead><tbody><tr><td>&quot;安装后浏览器打不开 1880 端口&quot;</td><td>先用 <code>node-red-status</code> 确认服务运行；再检查防火墙 <code>sudo ufw status</code>；再检查端口 `netstat -tlnp</td></tr><tr><td>&quot;Modbus 节点找不到&quot;</td><td>安装完成后需要刷新页面（Ctrl+R），节点才会出现在左侧面板</td></tr><tr><td>&quot;节点安装失败&quot;</td><td>检查网络连接；尝试用 npm 手动安装：<code>cd ~/.node-red &amp;&amp; npm install node-red-contrib-modbus</code></td></tr></tbody></table><hr><h3 id="第3次课-3-3-六大协议华山论剑" tabindex="-1">第3次课：3.3 六大协议华山论剑 <a class="header-anchor" href="#第3次课-3-3-六大协议华山论剑" aria-label="Permalink to &quot;第3次课：3.3 六大协议华山论剑&quot;">​</a></h3><h4 id="教学导入-5分钟-1" tabindex="-1">教学导入（5分钟） <a class="header-anchor" href="#教学导入-5分钟-1" aria-label="Permalink to &quot;教学导入（5分钟）&quot;">​</a></h4><p>快速回顾：3.1 节的三种解决思路（统一协议/协议网关/通用中间层），引出六种主流协议。</p><h4 id="知识讲解-70分钟" tabindex="-1">知识讲解（70分钟） <a class="header-anchor" href="#知识讲解-70分钟" aria-label="Permalink to &quot;知识讲解（70分钟）&quot;">​</a></h4><p><strong>六种协议讲解顺序</strong>（建议按教材顺序）：</p><table tabindex="0"><thead><tr><th>协议</th><th>归属厂商</th><th>核心特点</th><th>一句话口诀</th></tr></thead><tbody><tr><td>Profibus</td><td>西门子</td><td>老款总线，紫色线</td><td>紫色线=老款</td></tr><tr><td>ProfiNet</td><td>西门子</td><td>新款工业以太网，绿色线</td><td>绿色线=新款</td></tr><tr><td>EtherCAT</td><td>倍福</td><td>飞读飞写，极快</td><td>快=运动控制</td></tr><tr><td>CC-Link IE</td><td>三菱</td><td>环形冗余</td><td>日系=环形冗余</td></tr><tr><td>Modbus</td><td>施耐德(开放)</td><td>最老最开放</td><td>免费=最低门槛</td></tr><tr><td>EtherNet/IP</td><td>罗克韦尔</td><td>北美主流</td><td>CIP=北美</td></tr></tbody></table><p><strong>每种协议的讲解要点</strong>（每个8-10分钟）：</p><ol><li><p><strong>Profibus/ProfiNet（15分钟）</strong></p><ul><li>重点区分&quot;同一厂商的两代产品&quot;</li><li>物理层对比（RS-485 vs 以太网）</li><li>一句话口诀：紫色线=老款，绿色线=新款</li></ul></li><li><p><strong>EtherCAT（10分钟）</strong></p><ul><li>&quot;飞读飞写&quot;是理解核心，用图示讲解数据帧穿过从站的过程</li><li>类比：数据帧像一辆公交车，每站停车上（下）客，Bus Stop Network</li><li>强调：物理层和普通以太网完全一样（所以成本低）</li></ul></li><li><p><strong>CC-Link IE（8分钟）</strong></p><ul><li>环形拓扑的冗余机制是亮点</li><li>日系工厂（丰田、三菱）标配</li></ul></li><li><p><strong>Modbus（20分钟）</strong></p><ul><li>四种寄存器类型（线圈/离散输入/保持寄存器/输入寄存器）是重点</li><li>用功能码表格让学生记忆5个最常用的码</li><li>强调最大优势（免费开放）和最大局限（从站不能主动通信）</li></ul></li><li><p><strong>Powerlink/DeviceNet/EtherNet/IP（7分钟）</strong></p><ul><li>简要带过，作为知识面拓展</li><li>EtherNet/IP 是罗克韦尔的主推，注意和 ProfiNet 的对比</li></ul></li><li><p><strong>五种传输介质（10分钟）</strong></p><ul><li>RJ45工业级/DB9/M12/屏蔽双绞线/工业交换机</li><li>实物展示（如果有）：让学生触摸 RJ45 工业头和普通头的区别</li></ul></li></ol><h4 id="课程思政融入-10分钟" tabindex="-1">课程思政融入（10分钟） <a class="header-anchor" href="#课程思政融入-10分钟" aria-label="Permalink to &quot;课程思政融入（10分钟）&quot;">​</a></h4><p>乌克兰电网案例的讲解要点：</p><ol><li>描述事件经过：攻击者利用 IEC 104 协议漏洞，远程操控断路器</li><li>引导学生思考：消费互联网被攻击最多是&quot;网页打不开&quot;，工业系统被攻击是&quot;工厂爆炸&quot;</li><li>引出工程伦理：协议工程师的一行代码可能关系到生命安全</li><li>讨论问题：为什么工业协议对&quot;确定性&quot;和&quot;可靠性&quot;要求远高于消费协议？</li></ol><h4 id="回顾讨论-5分钟-1" tabindex="-1">回顾讨论（5分钟） <a class="header-anchor" href="#回顾讨论-5分钟-1" aria-label="Permalink to &quot;回顾讨论（5分钟）&quot;">​</a></h4><p>让学生快速回答：</p><ol><li>&quot;哪几种协议用 RJ45 网线？&quot;（ProfiNet/EtherCAT/CC-Link IE/EtherNet/IP）</li><li>&quot;Modbus 最大的局限是什么？&quot;（从站不能主动通信）</li><li>&quot;哪种协议的物理层和普通以太网一样？&quot;（EtherCAT）</li></ol><h4 id="常见问题与解答-2" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-2" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>解答</th></tr></thead><tbody><tr><td>&quot;ProfiNet 和工业以太网是一回事吗？&quot;</td><td>不完全相同。工业以太网是泛指所有基于以太网技术的工业协议；ProfiNet 是其中一种具体实现，还有 EtherCAT、EtherNet/IP 等。</td></tr><tr><td>&quot;Modbus RTU 和 ModbusTCP 能直接通信吗？&quot;</td><td>需要一个协议转换网关，不能直接通信。但两者使用相同的寄存器地址规则，转换相对简单。</td></tr><tr><td>&quot;为什么 EtherCAT 这么快？&quot;</td><td>不是因为带宽高（和普通以太网一样是100Mbps），而是因为处理方式高效——帧不用停下来等待每个从站处理，而是&quot;飞过&quot;每个从站时同步读写。</td></tr></tbody></table><hr><h3 id="第4次课-3-4-动手实践-modbustcp-通信实战" tabindex="-1">第4次课：3.4 动手实践：ModbusTCP 通信实战 <a class="header-anchor" href="#第4次课-3-4-动手实践-modbustcp-通信实战" aria-label="Permalink to &quot;第4次课：3.4 动手实践：ModbusTCP 通信实战&quot;">​</a></h3><h4 id="教学准备-1" tabindex="-1">教学准备 <a class="header-anchor" href="#教学准备-1" aria-label="Permalink to &quot;教学准备&quot;">​</a></h4><ul><li>确保每位学生已完成 3.2 节的 Node-RED 安装</li><li>预先在教师机上安装 QModMaster，用于课堂演示</li><li>打印任务单，确保学生动手时有记录表可填</li></ul><h4 id="教学导入-5分钟-2" tabindex="-1">教学导入（5分钟） <a class="header-anchor" href="#教学导入-5分钟-2" aria-label="Permalink to &quot;教学导入（5分钟）&quot;">​</a></h4><p>回顾 Modbus 协议的四类寄存器和功能码，为实验做知识准备。</p><h4 id="分步演示与学生操作-75分钟-1" tabindex="-1">分步演示与学生操作（75分钟） <a class="header-anchor" href="#分步演示与学生操作-75分钟-1" aria-label="Permalink to &quot;分步演示与学生操作（75分钟）&quot;">​</a></h4><p><strong>任务一：搭建 ModbusTCP 从站（25分钟）</strong></p><p>这是本节最关键的步骤：</p><ol><li>讲解 Modbus Server 节点的配置参数（类型/端口/从站ID）</li><li>演示配置三个寄存器：温度/状态/湿度</li><li>学生操作，教师巡视</li><li>重点讲解：为什么用 8502 而不是默认的 502？（避免权限问题）</li></ol><p><strong>验证方法</strong>：点击&quot;完成&quot;后 Server 节点显示&quot;已连接&quot;状态。</p><p><strong>任务二：搭建 ModbusTCP 主站（20分钟）</strong></p><ol><li>讲解轮询机制：主站每2秒自动读取一次寄存器</li><li>演示 Modbus Read 节点的配置</li><li>学生操作，点击部署</li><li>观察 Debug 面板的输出，理解&quot;轮询&quot;的含义</li></ol><p><strong>验证方法</strong>：Debug 面板每2秒输出新数据。</p><p><strong>任务三：QModMaster 直连（15分钟）</strong></p><p>这是对比理解的关键环节：</p><ol><li>教师演示：连接配置、读取寄存器 0（应为256）</li><li>学生操作：在寄存器 0 写入 300，观察 Node-RED Debug 面板的变化</li><li>讲解：QModMaster 相当于一个&quot;手动控制器&quot;，和主站一样在访问同一个从站</li></ol><p><strong>任务四：制造并排查故障（15分钟）</strong></p><p>这是培养故障排查能力的核心环节：</p><ol><li>让学生故意把端口改为 8503，部署，观察&quot;Connection refused&quot;</li><li>改回 8502，部署，观察恢复</li><li>引导学生思考：和&quot;打电话拨错号码&quot;的类比</li></ol><h4 id="故障排查引导-10分钟" tabindex="-1">故障排查引导（10分钟） <a class="header-anchor" href="#故障排查引导-10分钟" aria-label="Permalink to &quot;故障排查引导（10分钟）&quot;">​</a></h4><p>当&quot;通信不通&quot;时，按以下顺序排查：</p><ol><li><strong>物理层</strong>：网线是否插好？（最容易被忽略）</li><li><strong>IP 层</strong>：两端 IP 是否在同一网段？（<code>ping</code> 命令测试）</li><li><strong>端口层</strong>：端口号是否一致？（本次实验中最常见的错误）</li><li><strong>从站 ID</strong>：主站配置的从站 ID 是否和从站一致？</li><li><strong>防火墙</strong>：<code>sudo ufw status</code> 检查防火墙状态</li></ol><h4 id="回顾讨论-5分钟-2" tabindex="-1">回顾讨论（5分钟） <a class="header-anchor" href="#回顾讨论-5分钟-2" aria-label="Permalink to &quot;回顾讨论（5分钟）&quot;">​</a></h4><p>让学生复述 ModbusTCP 通信的三个组成部分（从站/主站/调试工具）及其作用。</p><h4 id="常见问题与解答-3" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-3" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><table tabindex="0"><thead><tr><th>问题</th><th>解答</th></tr></thead><tbody><tr><td>&quot;Modbus Read 节点一直显示黄色（未连接）&quot;</td><td>先确认 Modbus Server 已部署（显示绿色）；再检查主机 IP 是否为 127.0.0.1；再检查端口号是否一致</td></tr><tr><td>&quot;QModMaster 读取不到数据&quot;</td><td>检查 QModMaster 的 Modbus Mode 是否设为 TCP；检查 IP 和端口；尝试用 ping 命令先测试网络连通性</td></tr><tr><td>&quot;Debug 面板显示 NaN&quot;</td><td>说明寄存器值解析格式不对，检查功能码是否匹配（FC3 对应 Holding Register）</td></tr></tbody></table><h4 id="常见错误预判" tabindex="-1">常见错误预判 <a class="header-anchor" href="#常见错误预判" aria-label="Permalink to &quot;常见错误预判&quot;">​</a></h4><table tabindex="0"><thead><tr><th>错误</th><th>预防措施</th></tr></thead><tbody><tr><td>端口号记错（502/8502混淆）</td><td>强调实验用 8502 的原因；让学生在任务单上记录端口号</td></tr><tr><td>Modbus Read 节点功能码选错</td><td>复习五种功能码对应的数据类型；强调 FC3 对应 Holding Register</td></tr><tr><td>忘记点击&quot;部署&quot;</td><td>每次修改参数后提醒学生；解释&quot;部署=保存并运行&quot;的含义</td></tr></tbody></table><hr><h2 id="四、教学评价建议" tabindex="-1">四、教学评价建议 <a class="header-anchor" href="#四、教学评价建议" aria-label="Permalink to &quot;四、教学评价建议&quot;">​</a></h2><h3 id="过程性评价" tabindex="-1">过程性评价 <a class="header-anchor" href="#过程性评价" aria-label="Permalink to &quot;过程性评价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价维度</th><th>权重</th><th>观察点</th></tr></thead><tbody><tr><td>ISA-95 模型理解</td><td>20%</td><td>能准确说出每层的典型设备和问题</td></tr><tr><td>六种协议掌握</td><td>25%</td><td>能用&quot;一句话口诀&quot;准确描述每种协议</td></tr><tr><td>Node-RED 安装</td><td>20%</td><td>能独立完成安装并访问 Web 界面</td></tr><tr><td>ModbusTCP 通信实验</td><td>25%</td><td>能完整搭建从站+主站+QModMaster 通信链路</td></tr><tr><td>故障排查能力</td><td>10%</td><td>能独立诊断并解决通信参数不匹配问题</td></tr></tbody></table><h3 id="终结性评价" tabindex="-1">终结性评价 <a class="header-anchor" href="#终结性评价" aria-label="Permalink to &quot;终结性评价&quot;">​</a></h3><p><strong>笔试/口试题目</strong>（从思考与练习中选取）：</p><ol><li>简述 ISA-95 五层模型中 L0~L2 的核心职责</li><li>比较 ProfiNet 和 EtherCAT 在实时性实现机制上的差异</li><li>列举 Modbus 协议四种寄存器的名称和数据类型</li><li>分析&quot;从站不能主动通信&quot;这一局限对工业系统的影响</li></ol><h3 id="本章重点评价内容" tabindex="-1">本章重点评价内容 <a class="header-anchor" href="#本章重点评价内容" aria-label="Permalink to &quot;本章重点评价内容&quot;">​</a></h3><ol><li><strong>ISA-95 五层背诵</strong>：学生能不看资料说出 L0~L4 的层级名称和代表问题</li><li><strong>协议一句话口诀</strong>：能准确说出每种协议的核心特点</li><li><strong>Modbus 寄存器理解</strong>：能说出四种寄存器的读写属性</li></ol><hr><h2 id="五、教学资源清单" tabindex="-1">五、教学资源清单 <a class="header-anchor" href="#五、教学资源清单" aria-label="Permalink to &quot;五、教学资源清单&quot;">​</a></h2><h3 id="硬件设备" tabindex="-1">硬件设备 <a class="header-anchor" href="#硬件设备" aria-label="Permalink to &quot;硬件设备&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>数量</th><th>用途</th></tr></thead><tbody><tr><td>安装 VMware 的 Windows PC</td><td>每生1台</td><td>运行 Ubuntu 虚拟机</td></tr><tr><td>网络交换机（8口）</td><td>每组1台</td><td>小型局域网实验</td></tr><tr><td>RJ45 工业网线（绿色/紫色各若干）</td><td>若干</td><td>展示 ProfiNet/Profibus 线缆</td></tr></tbody></table><h3 id="软件工具" tabindex="-1">软件工具 <a class="header-anchor" href="#软件工具" aria-label="Permalink to &quot;软件工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>软件</th><th>版本</th><th>获取方式</th></tr></thead><tbody><tr><td>VMware Workstation Pro</td><td>17.x</td><td>学校许可</td></tr><tr><td>Ubuntu Server</td><td>22.04 LTS</td><td>免费下载</td></tr><tr><td>Node-RED</td><td>3.x</td><td>官方脚本安装</td></tr><tr><td>node-red-contrib-modbus</td><td>最新版</td><td>Node-RED 管理面板安装</td></tr><tr><td>QModMaster</td><td>0.9.x</td><td><a href="https://sourceforge.net/projects/qmodmaster/" target="_blank" rel="noreferrer">https://sourceforge.net/projects/qmodmaster/</a></td></tr></tbody></table><h3 id="教学挂图" tabindex="-1">教学挂图 <a class="header-anchor" href="#教学挂图" aria-label="Permalink to &quot;教学挂图&quot;">​</a></h3><ol><li><strong>ISA-95 五层金字塔挂图</strong>（A2幅面，每组1张）</li><li><strong>六种工业协议对比表</strong>（A2幅面，每组1张）</li><li><strong>Modbus 寄存器与功能码速查表</strong>（A4塑封，每人1张）</li></ol><h3 id="视频资源" tabindex="-1">视频资源 <a class="header-anchor" href="#视频资源" aria-label="Permalink to &quot;视频资源&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>标题</th><th>时长</th><th>用途</th></tr></thead><tbody><tr><td>I IoT-V3-01</td><td>Node-RED 安装与 ISA-95 节点关联</td><td>约15分钟</td><td>第2次课前预习</td></tr><tr><td>I IoT-V3-02</td><td>ModbusTCP 通信模拟实战</td><td>约20分钟</td><td>第4次课前预习</td></tr></tbody></table><hr><h2 id="六、思考与练习参考答案" tabindex="-1">六、思考与练习参考答案 <a class="header-anchor" href="#六、思考与练习参考答案" aria-label="Permalink to &quot;六、思考与练习参考答案&quot;">​</a></h2><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题号</th><th>答案</th><th>解析</th></tr></thead><tbody><tr><td>1</td><td>B</td><td>PLC 的核心职责是控制逻辑（L1），不是感知（L0）也不是监控（L2）</td></tr><tr><td>2</td><td>C</td><td>Profibus 使用 RS-485（DB9接头），其余五种均基于以太网（RJ45）</td></tr><tr><td>3</td><td>B</td><td>EtherCAT 的&quot;飞读飞写&quot;机制是其高速的核心；帧像火车穿过每个从站，从站不解包直接读写</td></tr><tr><td>4</td><td>C</td><td>Modbus 是唯一完全免费开放的协议；ProfiNet/EtherCAT/CC-Link IE 均需厂商认证</td></tr><tr><td>5</td><td>B</td><td>Modbus RTU 基于 RS-485 串行总线；ModbusTCP 才用以太网</td></tr><tr><td>6</td><td>B</td><td>线圈（Coil）是单比特（1位）开关量，可读可写；寄存器是16位（2字节）</td></tr><tr><td>7</td><td>C</td><td>CC-Link IE 环形拓扑任一点断线可自动切换为两条线型网络继续工作，是其最大优势</td></tr><tr><td>8</td><td>D</td><td>Wi-Fi 6E 是 WiFi 标准，不是 5G 的工业特性；eMBB/mMTC/uRLLC 均是 3GPP 定义的 5G 特性</td></tr></tbody></table><h3 id="判断题" tabindex="-1">判断题 <a class="header-anchor" href="#判断题" aria-label="Permalink to &quot;判断题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>题号</th><th>答案</th><th>解析</th></tr></thead><tbody><tr><td>1</td><td>√</td><td>ProfiNet 和 Profibus 均由西门子主导开发，属于西门子生态</td></tr><tr><td>2</td><td>√</td><td>EtherCAT 在物理层使用标准以太网和 RJ45 接口，这让其硬件成本低且兼容性好</td></tr><tr><td>3</td><td>×</td><td>Modbus 通信采用主从模式，从站不能主动向主站发送数据；报警需由主站轮询检测</td></tr><tr><td>4</td><td>√</td><td>屏蔽双绞线（STP）通过铝箔或编织网屏蔽层减少电磁干扰，是工业环境的首选</td></tr><tr><td>5</td><td>√</td><td>M12 连接器符合 IEC 61076-2-101 标准，防护等级可达 IP67，常见于传感器和现场设备</td></tr><tr><td>6</td><td>√</td><td>VPN（Virtual Private Network）通过加密隧道技术在公用网络上建立虚拟专用网络</td></tr><tr><td>7</td><td>√</td><td>Input Register（功能码 FC04）只读；Holding Register（FC03/FC06）可读写</td></tr><tr><td>8</td><td>×</td><td>Node-RED 是 IBM 开发并完全开源的项目（Apache 2.0 许可证），完全免费</td></tr><tr><td>9</td><td>√</td><td>npm（Node Package Manager）是 Node.js 生态的默认包管理器，Node-RED 依赖它安装节点</td></tr><tr><td>10</td><td>×</td><td>DeviceNet 基于 CAN 总线物理层（不是工业以太网），适合北美旧款设备；EtherNet/IP 基于工业以太网</td></tr></tbody></table><h3 id="思考题参考答案" tabindex="-1">思考题参考答案 <a class="header-anchor" href="#思考题参考答案" aria-label="Permalink to &quot;思考题参考答案&quot;">​</a></h3><p><strong>第1题</strong>： ProfiNet 是西门子新一代工业以太网协议，使用绿色工业网线（RJ45接口），支持微秒级实时通信；Profibus 是西门子老款现场总线协议，使用紫色屏蔽双绞线（DB9接口），RS-485 物理层，最高 12 Mbps。两者都是西门子家的，但 ProfiNet 是 Profibus 的&quot;升级换代&quot;产品。</p><p><strong>第2题</strong>： 选择 Modbus TCP（基于以太网）或 Modbus RTU（基于 RS-485）。理由：① 完全免费，任何 PLC 都原生支持；② 实现门槛最低，几行代码即可完成开发；③ 最开放，几乎所有传感器和仪表厂商都支持 Modbus。</p><p><strong>第3题</strong>： 这台 PLC 同时与 L1（控制传送带启停）和 L2（向 SCADA 上报数据）进行交互——在 L1 层它是控制器，在 L2 层它是数据采集点。</p><p><strong>第4题</strong>： 和&quot;打电话拨错号码&quot;相似之处：端口号就像电话号码，错了就找不到目标设备。最先检查的三个参数：① <strong>端口号</strong>（8502 还是 8503？）；② <strong>IP 地址</strong>（127.0.0.1 还是其他？）；③ <strong>从站 ID</strong>（从站配置的 ID 和主站请求的 ID 是否一致？）。</p><hr><h2 id="七、学生常见错误预判" tabindex="-1">七、学生常见错误预判 <a class="header-anchor" href="#七、学生常见错误预判" aria-label="Permalink to &quot;七、学生常见错误预判&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误类型</th><th>具体表现</th><th>预防措施</th><th>解决方法</th></tr></thead><tbody><tr><td>安装中断</td><td>安装 Node-RED 时网络断开</td><td>提前测试网络稳定性</td><td>重新运行安装命令（幂等操作）</td></tr><tr><td>端口混淆</td><td>把 Modbus Server 端口设为 502（权限不足）</td><td>强调用 8502 的原因</td><td>查看报错日志，改为 8502</td></tr><tr><td>功能码选错</td><td>用 FC3 读 Coil（应该用 FC1）</td><td>讲清楚五种功能码对应的数据类型</td><td>复习寄存器类型对照表</td></tr><tr><td>忘记部署</td><td>修改参数后看不到效果</td><td>每次修改后提醒&quot;部署&quot;</td><td>点击红色&quot;部署&quot;按钮</td></tr><tr><td>IP 记错</td><td>QModMaster 连接时用错了虚拟机 IP</td><td>要求学生把 IP 写在任务单上</td><td><code>ip addr</code> 命令重新查看</td></tr><tr><td>防火墙阻挡</td><td>QModMaster 连接超时</td><td>安装后执行 <code>sudo ufw allow 8502/tcp</code></td><td>检查并开放端口</td></tr></tbody></table>',136)])])}const c=d(e,[["render",l]]);export{q as __pageData,c as default};
